# Write a trust-all SSL provider
cat > /tmp/TrustAll.java << 'EOF'
import javax.net.ssl.*;
import java.security.*;
import java.security.cert.*;

public class TrustAll {
    public static void install() throws Exception {
        TrustManager[] trustAllCerts = new TrustManager[]{
            new X509TrustManager() {
                public X509Certificate[] getAcceptedIssuers() { return new X509Certificate[0]; }
                public void checkClientTrusted(X509Certificate[] certs, String authType) {}
                public void checkServerTrusted(X509Certificate[] certs, String authType) {}
            }
        };
        SSLContext sc = SSLContext.getInstance("TLS");
        sc.init(null, trustAllCerts, new SecureRandom());
        HttpsURLConnection.setDefaultSSLSocketFactory(sc.getSocketFactory());
        HttpsURLConnection.setDefaultHostnameVerifier((hostname, session) -> true);
    }
    public static void main(String[] args) throws Exception { install(); }
}
EOF

# Compile and package as a jar
mkdir -p /tmp/trustall
cd /tmp/trustall
javac /tmp/TrustAll.java -d . 2>&1
jar cvf trustall.jar TrustAll.class 2>&1
echo "Done building trust-all jar"

